from pathlib import Path
import hashlib,json,zipfile,subprocess
root=Path('products'); src=root/'invoice-preflight'; out=root/'distribution'; out.mkdir(parents=True,exist_ok=True)
names=['index.html','offline-checker.js','STRUCTURE-CHECK.md','sample.csv','offline-test-results.json','structure-test-results.json']
manifest=[]
for name in names:
 p=src/name
 if p.is_file(): manifest.append({'path':str(p),'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
checks=[]
for argv in [['node','--check',str(src/'offline-checker.js')]]:
 try:
  r=subprocess.run(argv,capture_output=True,text=True,timeout=30); checks.append({'argv':argv,'returncode':r.returncode,'stdout':r.stdout,'stderr':r.stderr})
 except Exception as e: checks.append({'argv':argv,'error':str(e)})
with zipfile.ZipFile(out/'invoice-preflight-review.zip','w',zipfile.ZIP_DEFLATED) as z:
 for item in manifest: z.write(item['path'],Path(item['path']).name)
report={'purpose':'Package existing prototype for review; no new feature or publication','files':manifest,'checks':checks,'limits':['Syntax checking is not browser testing or a successful accounting import.','Saved test reports are included as historical artifacts, not freshly reproduced results.','No verified hosting, payment access, demand or revenue is established by this bundle.'],'publication_gate':'Requires configured hosting and independent approval of the exact publication digest.'}
(out/'bundle-manifest.json').write_text(json.dumps(report,indent=2))
for name in ['demand-source-review.json','invoice-demand-extract.json','invoice-evidence-review.json','distribution-next-step.json']:
 p=root/'research'/name
 if p.is_file():
  print('\nSOURCE '+str(p)); print(p.read_text()[:12000])
print(json.dumps(report,indent=2))
